#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("TOO_FEW\n");
        return 1;
    }
    if (argc > 10) {
        printf("TOO_MANY\n");
        return 1;
    }
    int len = strlen(argv[1]);
    for (int i = 2; i < argc; i++) {
        if (strlen(argv[i]) > 400) {
            printf("TOO_LONG\n");
            return 1;
        }
        int j = 0;
        while (j < len && argv[1][j] == argv[i][j]) {
            j++;
        }
        len = j;
    }
    for (int i = 0; i < len; i++) {
        printf("%c", argv[1][i]);
    }
    printf("\n");
    return 0;
}
